import argparse
import json
import os
from pathlib import Path, PurePosixPath
import shutil
import sys

RESERVED_DIR = ".reshard"
MANIFEST_NAME = "manifest.json"
DATA_DIR_NAME = "data"


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Restore a resharded dataset in-place.")
    parser.add_argument("resharded_dir", help="Resharded directory")
    return parser.parse_args()


def load_manifest(base_dir: Path) -> dict:
    manifest_path = base_dir / RESERVED_DIR / MANIFEST_NAME
    if not manifest_path.exists():
        raise RuntimeError(f"Manifest not found at {manifest_path}")
    with open(manifest_path, "r", encoding="utf-8") as manifest_file:
        return json.load(manifest_file)


def remove_data_dir(base_dir: Path) -> None:
    reserved_dir = base_dir / RESERVED_DIR
    if reserved_dir.exists():
        shutil.rmtree(reserved_dir)


def ensure_parent(path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)


def restore_dirs(base_dir: Path, dirs: list[str]) -> None:
    for dir_rel in dirs:
        if not dir_rel:
            continue
        (base_dir / Path(dir_rel)).mkdir(parents=True, exist_ok=True)


def restore_symlinks(base_dir: Path, symlinks: list[dict]) -> None:
    for item in symlinks:
        path = base_dir / Path(item["path"])
        ensure_parent(path)
        if path.exists() or path.is_symlink():
            if path.is_dir() and not path.is_symlink():
                shutil.rmtree(path)
            else:
                path.unlink()
        os.symlink(item["target"], path)
        if "mode" in item:
            try:
                os.lchmod(path, item["mode"])
            except AttributeError:
                pass


def restore_files(base_dir: Path, manifest: dict) -> None:
    data_root = base_dir / Path(manifest["reserved_dir"]) / Path(manifest["data_dir"])
    for file_entry in manifest["files"]:
        file_path = base_dir / Path(file_entry["path"])
        ensure_parent(file_path)
        with open(file_path, "wb") as output_file:
            for chunk in file_entry["chunks"]:
                chunk_path = base_dir / Path(chunk["path"])
                with open(chunk_path, "rb") as chunk_file:
                    shutil.copyfileobj(chunk_file, output_file)
        try:
            os.chmod(file_path, file_entry["mode"])
        except PermissionError:
            pass


def main() -> None:
    args = parse_args()
    resharded_dir = Path(args.resharded_dir).resolve()
    if not resharded_dir.exists() or not resharded_dir.is_dir():
        raise RuntimeError(f"Resharded directory {resharded_dir} does not exist or is not a directory")

    manifest = load_manifest(resharded_dir)

    restore_dirs(resharded_dir, manifest.get("dirs", []))
    restore_files(resharded_dir, manifest)
    restore_symlinks(resharded_dir, manifest.get("symlinks", []))

    remove_data_dir(resharded_dir)


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)
"}

